const EXTENSION_CELLS_NL = {
  ARTIST_CAREGIVER: {"gift":"Scheppen voor verbinding: vertaalt rauwe, eenzame emotie in verhalen die de groep helen; de verhalenverteller wiens vertellingen de manier zijn waarop de gemeenschap zich herinnert dat ze één is.","curse":"Disharmonie in de groep → ontwijkt de harde artistieke waarheid om de vrede en het publiek te bewaren; het verhaal gezoet tot het niet langer voedt."},
  ARTIST_EXPLORER: {"gift":"Scheppen gekoppeld aan ontdekking: kijkt decennia vooruit, voorspelt de vorm die eraan komt, verlicht de toekomst zo levendig dat anderen er al vroeg naartoe beginnen te bouwen.","curse":"Analyseverlamming in het nu → zware stress wanneer het heden aanwezigheid eist; de visionair die leeft op een coördinaat die geen kalender kan bereiken."},
  ARTIST_HERO: {"gift":"Scheppen ontmoet ijzeren wil: smeedt de wereld actief om; ontwerp dwars door materiële weerstand heen gedreven; de smid die het gereedschap maakt waarmee daarna geschiedenis wordt gemaakt.","curse":"Innovatieblokkade → agressieve onderdrukking van emoties, extreme tunnelvisie; offert zichzelf en de liefde op aan de smidse; de maker die stuk voor stuk in zijn eigen machine wordt gevoerd."},
  ARTIST_INNOCENT: {"gift":"Maakt vanuit pure helderheid: het werk dient zich aan in plaats van gebouwd te worden — geen ironie, geen berekening tussen oog en hand; een zuiverheid die geen training kan fabriceren. De wereld noemt het talent; talent was het nooit.","curse":"Het zuivere gewoon gebleken — de stroom opgeëist als bezit, opgevoerd als vaardigheid → het kanaal slibt dicht; vormen afgedwongen waar ze zich ooit aandienden; de bron die alleen nog haar eigen herinnering opvoert."},
  ARTIST_JUDGE: {"gift":"Het genadige mes: ziet wat een werk wil zijn en snijdt al het andere weg; de redacteur wiens schrappingen een vorm van geloof in de maker zijn.","curse":"De snede tegen alles gekeerd → niets overleeft de revisie; perfectie als papierversnipperaar; redigeert het leven even meedogenloos als de pagina, tot van geen van beide nog een concept overeind staat."},
  ARTIST_LOVER: {"gift":"Kunst als het hofmaken van de wereld: zingt gevoel rechtstreeks toe aan wie het geldt; de troubadour wiens werk de afstand tussen harten overbrugt, live, in de zaal.","curse":"Het applaus als vervanger van de geliefde → brengt iedereen een serenade, bereikt niemand; speelt verlangen zo mooi dat het echte verlangen nooit aan de beurt komt om onopgesmukt te spreken."},
  ARTIST_MAGICIAN: {"gift":"Ambacht als transformatie: kent de geheime nerf van het materiaal en werkt MET de nerf mee; de ambachtsman wiens voorwerpen standhouden omdat hij begreep wat het materiaal zelf wilde worden.","curse":"Overal massaproductie en de kantjes eraf → verbittering; de standaard verheven tot priesterschap; perfecte stoelen gemaakt voor een wereld die onwaardig wordt bevonden om erop te zitten."},
  ARTIST_OUTLAW: {"gift":"Scheppen als ontploffing: maakt het werk dat de nette wereld niet meer kan ont-zien; de provocateur wiens beelden in één oogopslag doen wat honderd essays betoogden.","curse":"Shock als enig register → provoceert het doel voorbij; de ontploffing zonder lading; schandalen verzameld terwijl de boodschap verhongert."},
  ARTIST_RULER: {"gift":"Creatieve flow gevangen in briljante structuren: ontwerpt systemen en gebouwen die zowel mooi ALS bruikbaar zijn; vorm die het leven even trouw dient als het oog.","curse":"Mensen die zich niet aan de perfecte blauwdruk houden → genadeloos; de esthetiek verdedigd tegen haar bewoners; architectuur die met elk 'niet aankomen' verder afglijdt naar tirannie."},
  ARTIST_SAGE: {"gift":"Het hoogtepunt van de creatieve as: ontwerpt complete subjectieve universums en nieuwe paradigma's van bestaan; werelden zo samenhangend dat mensen erin trekken en volgens hun natuurwetten leven.","curse":"De grenzen van de werkelijkheid → weigering om compromissen te sluiten met de fysieke wereld; God-complex bij tegenslag; en de bewoners van de gemaakte wereld behandeld als personages, niet als mensen."},
  ARTIST_TRICKSTER: {"gift":"Waarheid overgebracht in symbolen: spreekt uit wat komen gaat in beelden die het heden kan bevatten; het orakel wiens raadsels barmhartigheid zijn — de toekomst gedoseerd zodat ze ontvangen kan worden.","curse":"Te letterlijk of helemaal niet geloofd worden → spreekt in steeds bedektere termen; verschuilt zich achter dubbelzinnigheid; het orakel dat nooit ook maar één keer betrapt werd op ronduit ongelijk, omdat het nooit ook maar één keer ronduit iets was."},
  CAREGIVER_ARTIST: {"gift":"Restauratie als kunst: herstelt wat beschadigd is — voorwerpen, huizen, mensen — met zoveel aandacht dat de reparatie deel wordt van de schoonheid; kintsugi als manier van zorgen.","curse":"Het onherstelbare → kan niet aanvaarden dat sommige dingen kapot blijven; blijft herstellen voorbij de grens van toestemming; of rouwt om elke barst als persoonlijk tekortschieten in zorg."},
  CAREGIVER_EXPLORER: {"gift":"Zorg in beweging: begeleidt de reis van een ander stap voor stap — de metgezel op de pelgrimstocht die de bepakking draagt als de weg steil wordt.","curse":"Het einde van de reis → weet niet hoe op te houden met naast de ander te lopen; vindt ofwel meteen een nieuwe pelgrim, ofwel staat verloren op de bestemming die nooit de eigen was."},
  CAREGIVER_HERO: {"gift":"Waakzame bescherming: houdt de wacht die niemand ziet, vangt op wat anders de kwetsbaren had bereikt; veiligheid die elke nacht wordt voortgebracht door iemand die er nooit over begint.","curse":"Nooit buiten dienst → wie de wapenrusting nooit afdoet, vergeet hoe de zon voelt; de wacht wordt de identiteit; beschermt iedereen tegen alles, behalve tegen de eigen afwezigheid."},
  CAREGIVER_INNOCENT: {"gift":"Onvoorwaardelijk geloof als zorg: ziet het goede in iemand nog voordat die het zelf kan zien, en verzorgt het trouw tot het wortel schiet.","curse":"De persoon in wie geloofd wordt faalt → het geloof verdubbelt in plaats van zich bij te stellen; toewijding aan het potentieel maakt blind voor het werkelijke; trouw aan wie iemand zou kunnen zijn, afwezig bij wie iemand is."},
  CAREGIVER_JUDGE: {"gift":"Bescherming met een vonnis in de hand: verdedigt de kwetsbaren door het onrecht hardop te benoemen; zorg die getuigt, procedeert, wint.","curse":"Een zaak die verloren gaat → draagt het lot van de cliënt als persoonlijk falen; of verdedigt zo fel dat de eigen stem van de beschermde nooit gehoord wordt in de rechtszaal."},
  CAREGIVER_LOVER: {"gift":"Dienstbaarheid versmolten met diepe intimiteit: geneest niet op armlengte afstand maar huid aan huid; de veilige haven waar echt gezien worden zelf het medicijn is.","curse":"Emotionele disharmonie → identiteit rust op het genezen; als de patiënt herstelt of zich verzet, valt de grond onder de genezer weg; zorg verglijdt tot co-afhankelijk vasthouden."},
  CAREGIVER_MAGICIAN: {"gift":"Bescherming door ontwerp: bevecht de dreiging niet aan de deur maar bouwt de deur; bezweringen, protocollen, voorzieningen — veiligheid zo volledig ontworpen dat het op geluk lijkt.","curse":"Controle aangezien voor zorg → de beschutting wordt een cel; houdt vast wat beschermd wordt; de bewaker die niet meer weet of de sloten naar buiten of naar binnen wijzen."},
  CAREGIVER_OUTLAW: {"gift":"Zorg die weet wanneer ze niet moet ingrijpen: houdt een hand open in plaats van de genezing af te dwingen; laat mensen groeien zoals een tuinier dat doet — omstandigheden, geen bevelen.","curse":"Toezien hoe een destructief patroon zich herhaalt → de drang om het voor de ander te doorbreken; wordt die te lang ingehouden, dan explodeert hij in een reddingsactie of verhardt hij tot afstandelijkheid."},
  CAREGIVER_RULER: {"gift":"Compassie als georganiseerde kracht: bouwt het huishouden, de instelling, het geslacht dat op grote schaal beschermt; voorzienigheid met een ruggengraat van bestuur.","curse":"Anarchie of ondankbaarheid → verstikking; voorzien wordt een drukmiddel; het gezin zo veilig vastgehouden dat niemand erin volwassen mag worden."},
  CAREGIVER_SAGE: {"gift":"Zorg vanuit psychologisch inzicht: ziet het mechanisme onder het lijden; een bron die zichzelf aanvult, omdat begrijpen niet opbrandt zoals absorberen dat doet.","curse":"Overanalyse → niet alle pijn heeft een vindbare oorzaak; de zoektocht naar het waarom wordt een manier om niet bij het wat te hoeven blijven; de patiënt verklaard, niet begeleid."},
  CAREGIVER_TRICKSTER: {"gift":"De emotionele radar in dienst van zorg: voelt welk onuitgesproken weer er in de kamer hangt, bereikt degene die alle anderen misten; troost geboden nog vóór de tranen.","curse":"Absorberen wat er gelezen wordt → neemt elke kamer mee naar huis; grenzen lossen op in de toestand van de ander; de empaat die verdrinkt in signalen die nooit de eigen last waren."},
  EXPLORER_ARTIST: {"gift":"De weg die lied werd: verzamelt de verhalen van de wereld en draagt ze van plek naar plek; de bard wiens reis het archief IS, wiens vertellen vreemden tot verwanten maakt.","curse":"Geen publiek, geen haard → de liederen verzuren; voert de reis op in plaats van die te beleven; een leven zo onafgebroken verteld dat het nooit helemaal werd bijgewoond."},
  EXPLORER_CAREGIVER: {"gift":"Paden vinden als dienst: gaat voorop, niet om de eer van de eerste, maar om de weg begaanbaar te maken voor degenen die volgen; markeert het pad, draagt de zwakken naar de overkant.","curse":"Niemand die volgt → doelloosheid; of weigert de volgers ooit te laten leiden; de padvinder die de verdwaalden harder nodig heeft dan de verdwaalden het pad."},
  EXPLORER_HERO: {"gift":"Bewezen veerkracht: overleeft alles — de storm, de stiltegordel, het verlies van de lading; uithoudingsvermogen zo diep dat het een vorm van navigatie is geworden.","curse":"Eindeloos overleven → de vraag is niet of ze het halen, maar of ze ooit ergens aankomen waar overleven niet nodig is; rust opgevat als overgave."},
  EXPLORER_INNOCENT: {"gift":"Kartering met een kompas van vertrouwen: verkent niet om te vluchten maar om in kaart te brengen; brengt objectieve nieuwe waarheden mee terug EN het geloof dat de overtocht de moeite waard is.","curse":"Stagnatie → ondraaglijk; berekent vanuit elke stilstand ontsnappingsvarianten; de kaart groeit terwijl de thuiscoördinaat voorgoed leeg blijft."},
  EXPLORER_JUDGE: {"gift":"Verkennen met een meetlint: meet het onbekende nauwkeurig op — wat er is, wat het waard is, waar de grens eerlijk loopt; de voorhoede waarvan de rapporten standhouden.","curse":"Betwiste grond → star; de verkenner die het instrument meer vertrouwt dan de bewoner; grenzen getrokken, correct en wreed."},
  EXPLORER_LOVER: {"gift":"Verwondering als verbinding: verkent omhoog en naar buiten en pakt daarbij iemands hand; de nachthemel, de verre kust, het onbekende — aangeboden als gedeelde verbazing.","curse":"Een metgezel die niet meer omhoogkijkt → drijft af naar het volgende paar ogen; houdt meer van het samen-verwonderen dan van het samen; horizonnen verzameld, havens afgeslagen."},
  EXPLORER_MAGICIAN: {"gift":"Meesterschap over het wortelloze leven: maakt van beweging zelf een thuis; middelen overal tevoorschijn getoverd, het thuisgevoel van binnen meegedragen; vrij omdat niets van buitenaf dragend is.","curse":"Een aangeboden wortel → paniek vermomd als principe; maakt van elk 'blijf' een reden om te gaan; de nomade wiens vrijheid een muur op wielen is."},
  EXPLORER_OUTLAW: {"gift":"Rusteloze vindingrijkheid met tanden: ziet niet alleen het volgende, maar breekt het huidige open om dat volgende te bouwen; innovatie als productieve rebellie.","curse":"Het gemaakte in de steek laten → een spoor van briljante wezen; het ontbreekt de wereld niet aan uitvindingen, maar aan mensen die ook na de wittebroodsweken bij hun uitvindingen blijven."},
  EXPLORER_RULER: {"gift":"Ontdekken via mensen, georganiseerd: bouwt het netwerk als infrastructuur — introducties, allianties, routes tussen werelden; de verbinder wiens kaart uit namen bestaat.","curse":"Sociale uitsluiting of een statische kring → de motor slaat af; verzamelt contacten voorbij het punt van contact; vriend van iedereen, verankerd bij niemand."},
  EXPLORER_SAGE: {"gift":"De filosofie van de weg: reist om te begrijpen, niet om te verzamelen; elke overschreden grens wordt een getoetst concept; wijsheid met stof op de laarzen.","curse":"Ontlichaming → theorie losgezongen van de grond; de filosoof die overal is geweest en niets heeft aangeraakt; inzicht dat nooit landt omdat het nooit blijft."},
  EXPLORER_TRICKSTER: {"gift":"De scout die de listen van het land leest: ziet de hinderlaag, de kortere weg, het veelzeggende spoor in het terrein; reist licht bepakt, komt als eerste aan, lacht om de fouten van de kaart.","curse":"Verlies van het eigen discipline-anker → drijft af; slimheid zonder missie verkent in rondjes; de eerste die overal aankomt en zich nergens aan bindt."},
  HERO_ARTIST: {"gift":"Strijd als ambacht: het duel prachtig uitgevochten — precisie, stijl, eer; wint op een manier die zelfs de verliezers meesterlijk noemen.","curse":"Een lelijk, noodzakelijk gevecht → weigert het; esthetiek boven uitkomst; de duellist die liever schitterend verliest dan zonder gratie wint, en dat principe noemt."},
  HERO_CAREGIVER: {"gift":"Vechtkracht voor compassie: het menselijk schild; vangt elke klap op voor de kwetsbaren en doorstaat onmogelijke ontberingen om anderen heel te houden.","curse":"Andermans lijden niet te voorkomen → het schild dat nooit om hulp vraagt, breekt als eerste; bescherming gegeven als een schuld die niemand ooit mag aflossen."},
  HERO_EXPLORER: {"gift":"Het onmogelijke met discipline ondernomen: traint jarenlang om te doorkruisen wat nog niemand doorkruiste; heldendom gericht op de grens zelf in plaats van op een vijand.","curse":"Geen lanceervenster → de gedrevenheid corrodeert naar binnen; de aarde voelt als een nederlaag; een leven afgesteld op het uitzonderlijke dat een gewone dinsdag niet kan verteren."},
  HERO_INNOCENT: {"gift":"Wil in dienst van een stralende zaak: vecht met totale overtuiging voor het goede; de kruistocht die bergen verzet omdat haar soldaat oprecht gelooft.","curse":"De zaak onzuiver bevonden → kan het zich niet veroorloven dat te zien; zet nog harder door; de kruisvaarder die het dorp platbrandt om het verhaal te redden dat hij over zichzelf vertelt."},
  HERO_JUDGE: {"gift":"Kracht onder gelofte: vecht alleen voor wat gewogen en rechtvaardig bevonden is; de krijger wiens terughoudendheid even gevreesd is als zijn zwaard; macht die haar eed houdt.","curse":"De code verraden door de eigen kerk → crisis; voert óf een fellere kruistocht om de twijfel het zwijgen op te leggen, óf breekt volledig; rechtvaardigheid verkalkt tot precies datgene waartegen de gelofte gericht was."},
  HERO_LOVER: {"gift":"Ridderlijke toewijding: kracht volledig in dienst gesteld van één geliefde — de gelofte, het gunstbewijs, het ertussen staan; liefde uitgedrukt als bewakende aanwezigheid.","curse":"Een geliefde die geen redding nodig heeft → doelloos; verzint draken; de ridder die meer houdt van het redden dan van de persoon, en het voetstuk toewijding noemt."},
  HERO_MAGICIAN: {"gift":"Zuivere heldenwil op zijn zenit: de prestatie die een verhaal wordt waar anderen naar leven; veerkracht zo volledig dat ze verandert wat mensen voor mogelijk houden.","curse":"De kruik gaat zo lang te water tot hij breekt — en zij WAREN de kruik; de legende overeind gehouden nadat het lichaam al bezwaar had aangetekend; applaus aangezien voor brandstof."},
  HERO_OUTLAW: {"gift":"Ongebonden kracht: slaat toe waar trage legers dat niet kunnen; neemt wat het verschanste onrecht had opgepot; de strooptocht als chirurgie op een verrotte orde.","curse":"Geen waardig doelwit → het plunderen wordt het doel op zich; roof zonder reden; kracht die, zonder betekenis werkloos, de rekening bij de onschuldigen gaat neerleggen."},
  HERO_RULER: {"gift":"Verovering die standhoudt: wint het terrein EN organiseert het; kracht omgezet in gevestigde orde; de veldtocht die eindigt in een functionerende vrede.","curse":"Een rijk in rust → rusteloosheid; vrede gelezen als verval; de veroveraar die steeds nieuwe muren moet vinden omdat hij zichzelf alleen kent midden in een belegering."},
  HERO_SAGE: {"gift":"Uitvoering gevoed door diepe patronen: ziet de hele veldtocht vooruit, wint vóór de eerste zet; kracht vermenigvuldigd met begrip.","curse":"Worstcaseprojectie → verlamming door de gemodelleerde catastrofe; en de ene kostenpost die elk model wegliet — de strateeg zelf, verbruikt als pion."},
  HERO_TRICKSTER: {"gift":"De strijd gewonnen in de schaduw: infiltreert, leest, misleidt; de spion wiens grootste overwinningen de gevechten zijn die nooit hoefden plaats te vinden.","curse":"Geen handler, geen missie → identiteit lost op in dekmantels; de spion die zo lang iedereen is geweest dat 'ik' de enige legende is die nooit werd opgebouwd."},
  INNOCENT_ARTIST: {"gift":"De utopie zichtbaar gemaakt: schildert, schrijft, bouwt de betere wereld zo levendig dat anderen erheen beginnen te lopen; hoop met een beeld erbij.","curse":"Werkelijkheid die het ontwerp weigert → wanhoop of ontkenning; de utopist die meer houdt van het schilderij dan van de mensen voor wie het geschilderd werd."},
  INNOCENT_CAREGIVER: {"gift":"Paradijs gericht op de ander: onvoorwaardelijke, vreugdevolle hulp voor de vreemdeling; vergeving en zorg, gegeven zonder kasboek.","curse":"Cynische werkelijkheid die binnendringt → vlucht in ontkenning; helpt om het donker niet te hoeven voelen; goedheid als verdoving tegen het werkelijke gewicht van de wereld."},
  INNOCENT_EXPLORER: {"gift":"Belichaamde hoop in beweging: draagt fundamenteel vertrouwen naar cynische plekken en laat ze lichter achter; het absolute licht dat reist.","curse":"Beschuldiging van zonde → heftige innerlijke reactie; de heiligheid feller verdedigd dan de goedheid geleefd; zuiverheid als vesting tegen het volledig gezien worden."},
  INNOCENT_HERO: {"gift":"Optimisme met handen en laarzen: gelooft dat het onbekende iets goeds herbergt EN gaat als eerste om het te bewijzen; de nederzetting die bestaat omdat iemand vol hoop ook onvermoeibaar was.","curse":"Verlies van vaart → burn-out; de op visie gevoede stresstolerantie stort in bij stilstand; vreest de pauze meer dan de wildernis."},
  INNOCENT_JUDGE: {"gift":"Traditie met een maatstaf: bewaart niet alles wat oud is, maar alles wat WAAR is in het oude; de gebruiken geselecteerd, de waarden getoetst, het erfgoed dat het bewaren verdient.","curse":"Komst van het nieuwe → oordeelt voordat er begrip is; de maatstaf verstart; verdedigt de letter van een traditie waarvan de geest het gebouw allang heeft verlaten."},
  INNOCENT_LOVER: {"gift":"Ontwapenende warmte: de aanwezigheid die ruimtes vriendelijker maakt; moeiteloos geliefd en moeiteloos liefhebbend; onschuld die harnassen doet smelten waarvan niemand wist dat ze die droegen.","curse":"Eerste verraad → de zoetheid schift of speelt toneel; blijft aanbiddelijk om veilig te zijn; de lieveling die iedereen aanbidt en niemand echt heeft ontmoet."},
  INNOCENT_MAGICIAN: {"gift":"Hoop die bij aanraking transformeert: stapt een vastgelopen situatie binnen en de dingen komen in beweging — niet door kracht, maar door de pure chemie van geloven dat verandering mogelijk is.","curse":"De reactie die niet op gang komt → twijfelt aan de eigen goedheid in plaats van aan de omstandigheden; blijft licht werpen in inerte kamers tot de bron opdroogt."},
  INNOCENT_OUTLAW: {"gift":"De fakkel op donkere plekken: brengt ongeschonden hoop in kapotte systemen; degene die het protest, de ziekenzaal, de ruïne binnenloopt en nog steeds gelooft — en dat geloof is besmettelijk.","curse":"Duisternis die niet wijkt → de fakkel sputtert; brandt óf op van licht dragen waar er geen terugkomt, óf ontkent het donker zo hard dat het getuigenis ophoudt eerlijk te zijn."},
  INNOCENT_RULER: {"gift":"Hoop verankerd in traditie: bewaart de waarden, de rituelen, het veld waar de kudde veilig is; continuïteit als een vorm van liefde.","curse":"Onvoorspelbaarheid → doodsangst onder de kalmte; bewaakt de weide zo star dat het gras sterft; bewaren verward met stilstand."},
  INNOCENT_SAGE: {"gift":"Zuivere hoop getrouwd met patroonzicht: ontwerpt en draagt het visioen van de volmaakte wereld of theorie; geloof met een architectuur.","curse":"Gebroken idealen → extreme gevoeligheid voor een wereld die niet aan het smetteloze ontwerp beantwoordt; rouw om een utopie die voor een belofte werd aangezien."},
  INNOCENT_TRICKSTER: {"gift":"Zuiverheid plus spel: weigert de zwaarte van regels zonder kwade opzet; de grens overgestoken met een lach die iedereen laat zien dat het hek denkbeeldig was.","curse":"Pragmatische inperking → hevige stress als de bubbel wordt doorgeprikt; vlucht in speelse fantasie; vrijheid des te harder opgevoerd naarmate ze minder gevoeld wordt."},
  JUDGE_ARTIST: {"gift":"Oordeel met een kennersoog: waardeert wat anderen over het hoofd zien, taxeert het onbetaalbare eerlijk; het vonnis dat een maker niet alleen vertelt wat er mis is, maar wat er ZELDZAAM is.","curse":"Kitsch beloond, meesterschap genegeerd → minachting; de taxatie verwordt tot poortwachterschap; vergeet dat smaak een lens is, en gaat die hanteren als wet."},
  JUDGE_CAREGIVER: {"gift":"IJzige objectiviteit verwarmd door zorg: herstelt gebroken relaties door beide kanten te wegen ÉN beide vast te houden; het oordeel waarmee mensen kunnen leven omdat ze allebei gezien zijn.","curse":"Emotionele afstand → schort de objectieve waarheid op om de vrede te bewaren; de bemiddeling die de kamer heelt en het onrecht stilletjes begraaft."},
  JUDGE_EXPLORER: {"gift":"De audit als expeditie: volgt het geld, het papierspoor, de afwijking door elk terrein; bevindingen die niemand kan betwisten omdat elke stap gelopen en vastgelegd is.","curse":"Een spoor dat doodloopt → kan het dossier niet sluiten; blijft door grootboeken reizen lang nadat het antwoord er niet meer toe deed; verificatie als manier om nooit aan te komen."},
  JUDGE_HERO: {"gift":"Gerechtigheid met handen: archiveert het onrecht niet, maar gaat erop af en maakt er een einde aan; beschermt de onderdrukten met een wil waar corruptie bang voor leert te zijn.","curse":"Machteloosheid → eigenrichting; wrede middelen voor juiste doelen; de wreker die het eigen vonnis niet meer toetst, is een wapen geworden dat denkt dat het een rechtbank is."},
  JUDGE_INNOCENT: {"gift":"Moreel wegen in dienst van het nieuwe: de ethische poortwachter die ideeën toetst zonder ze te doden; zuiverheid als maatstaf, hoop als de reden voor die maatstaf.","curse":"Stilstand of bederf van het zuivere → verlammend perfectionisme; geen kandidaat slaagt ooit; de poort wordt een muur, en de examinator zijn gevangene."},
  JUDGE_LOVER: {"gift":"Verzoening door gevoelde eerlijkheid: leest de pijn onder beide standpunten en spreekt die hardop uit; de schikking die aankomt omdat beide harten zichzelf erin hoorden.","curse":"Een kloof die resonantie niet kan overbruggen → vat het falen persoonlijk op; blijft lijmen wat wil eindigen; vrede nagestreefd voorbij het punt waarop de waarheid de mildere uitkomst was."},
  JUDGE_MAGICIAN: {"gift":"Handhaving door ontwerp: bouwt het mechanisme dat de overtreding onmogelijk maakt in plaats van bestraft; consequentie ingebouwd in het systeem zelf.","curse":"Een maas in de wet gevonden → de machinerie wordt strakker aangedraaid tot ze ook de onschuldigen vermaalt; handhaving zo totaal dat genade geen enkele interface meer heeft om binnen te komen."},
  JUDGE_OUTLAW: {"gift":"Objectieve wet, gewapend met ontwrichting: blaast corrupte systemen open om de waarheid bloot te leggen; de enige insider die bereid is de eigen positie op te blazen voor het dossier.","curse":"Hypocrisie aan de top → heftige stresspiek; de ontploffing wordt de identiteit; blijft openblazen wat een stillere hand had kunnen helen."},
  JUDGE_RULER: {"gift":"Onpartijdig gezag op systeemschaal: het vonnis dat bindt omdat de structuur erachter deugt; integriteit afgedwongen tot in elke hoek.","curse":"Systeemfouten → draconisch; straf zonder context; de arbiter die de code zo zuiver dient dat de zaak erachter verdwijnt."},
  JUDGE_SAGE: {"gift":"Kwaliteitscontrole op het niveau van de grondbeginselen: vindt de verborgen drogreden, de rot in de constructie, de hypocrisie in het argument zelf; de lat die iedereen stiekem wil halen.","curse":"Een denkfout die onweersproken blijft → obsessie met wat er niet klopt; cynisch gepieker; een geest die zo getraind is op gebreken dat die niet meer kan zien dat iets werkt."},
  JUDGE_TRICKSTER: {"gift":"Waarheidsvinding door verhoor: leest het schrikken, stelt de ene vraag die de leugen niet overleeft; corruptie niet ontmaskerd met een bom maar met een spiegel.","curse":"Een antwoord dat maar niet komt → het ondervragen wordt de wreedheid; verdenkt iedereen, maakt van elk gesprek een examen waarvoor niemand slaagt."},
  LOVER_ARTIST: {"gift":"Liefde die het maken ontsteekt: de aanwezigheid die andermans talent laat witgloeien; inspireert niet door kunst te eisen, maar door iemand te zijn voor wie het de moeite waard is om te maken.","curse":"De blik van de maker die dooft → instorting van de identiteit; bestaat alleen nog als weerspiegeling in het werk van anderen; de muze die nooit gevraagd werd wat zij zelf zou scheppen."},
  LOVER_CAREGIVER: {"gift":"De ultieme versmelting, geaard in zorg: voelt de ander niet alleen volledig aan, maar BOUWT ook om die ander heen; een band die zowel vuur als schuilplaats is.","curse":"Ervaren afstand → klampt zich vast door te zorgen; maakt zich onmisbaar om niet verlaten te kunnen worden; liefde toegediend als dienstverlening tot het eigen zelf de vermiste persoon is."},
  LOVER_EXPLORER: {"gift":"Liefde als pelgrimstocht: legt elke afstand af naar wat het vuur ontsteekt — een persoon, een plek, een transcendentie; passie met een kompas.","curse":"De vlam bereikt → cirkelt, brandt, kan niet landen en niet vertrekken; verwart de intensiteit van het naderen met de inhoud van het aankomen; vleugels ingeruild voor één felle nacht."},
  LOVER_HERO: {"gift":"Liefde met grote intensiteit en toewijding: gaat achter de band aan, vecht ervoor, is er — de romantiek die ook een discipline is.","curse":"Verwart intensiteit met waarheid → fabriceert stormen om te voelen dat de liefde zichzelf bewijst; kan niet blijven zitten in de stilte waar het echte woont."},
  LOVER_INNOCENT: {"gift":"Toewijding in haar zuiverste toonsoort: houdt helemaal en zonder ironie van één ding — een persoon, een ambacht, een geloof; standvastigheid die het beminde MEER waarachtig maakt.","curse":"Het object van toewijding blijkt het niet waard → de kleur trekt weg uit de wereld; ofwel ontkenning die het idool blijft oppoetsen, ofwel de ineenstorting van alles wat erop gebouwd was."},
  LOVER_JUDGE: {"gift":"Liefde die haar woord geeft: trouw als gekozen vonnis, de belofte die gewogen wordt voordat ze wordt uitgesproken en gehouden wordt als allang niemand meer kijkt.","curse":"Twijfel aan de gelofte van de ander → liefde verandert in bewijsvergaring; controleert genegenheid, houdt de stand bij; de verloofde wordt de verdachte."},
  LOVER_MAGICIAN: {"gift":"Betovering in de liefde: leest de verborgen hefbomen van verlangen en bespeelt ze als een instrument; maakt de wereld van de geliefde groter, vreemder, levendiger.","curse":"Magnetisme dat hapert → onzekerheid maakt van charme sturing; verleiding wordt het managen van andermans gevoel; de betovering die, eenmaal ontdekt, alles vergiftigt wat ze opbouwde."},
  LOVER_OUTLAW: {"gift":"Ontketende liefde: doorbreekt de zware sociale scripts rond verlangen; brengt ongecompliceerde vreugde waar plicht de ramen had dichtgemetseld; genot als eerlijke rebellie.","curse":"Gevoelde opsluiting → vlucht in frivoliteit; de genotzoeker die elke diepte aanziet voor een kooi en elke kooi voor een reden om weg te rennen; vrijheid die verhongert."},
  LOVER_RULER: {"gift":"Intimiteit verbonden aan orde: bouwt het gedeelde leven als een rijk — trouw, stabiel, bevoorraad; liefde als een fort met de deur aan de binnenkant.","curse":"Instabiliteit van het kader → doodsangst; als de regels van de relatie gaan wankelen, verstart emotioneel; verdedigt het fort zo fel dat de geliefde erbuiten gaat wonen."},
  LOVER_SAGE: {"gift":"Rauwe kwetsbaarheid met precisie vertaald: emotie die via begrip wordt omgezet in woorden waarin vreemden zich gekend voelen; de versregel die benoemt wat iedereen met zich meedroeg.","curse":"Verlies van inspiratie → melancholie bestudeerd in plaats van geleefd; ontleedt het eigen hart op zoek naar materiaal tot het gevoel op de snijtafel sterft."},
  LOVER_TRICKSTER: {"gift":"Bondgenoot van de liefde met perfecte timing: leest wat twee mensen niet tegen elkaar kunnen zeggen en slaat de brug met een grap; verbinding vernuftig aangelegd met lichtheid.","curse":"Altijd de brug, nooit de bestemming → verstopt het eigen verlangen achter de assist; de wingman die iedereen thuis laat landen en alleen, lachend, terugloopt."},
  MAGICIAN_ARTIST: {"gift":"De verandering in scène gezet: transformeert een zaal, een publiek, een markt door een optreden — de demonstratie zo overtuigend dat wie ernaar kijkt, daarmee al veranderd IS.","curse":"Applaus als maatstaf → speelt door waar de waarheid ophoudt; de act gepolijst tot die het werk vervangt; prestaties gecureerd in plaats van verdiend."},
  MAGICIAN_CAREGIVER: {"gift":"Transformatie VOOR iemand: daalt af in andermans ruïne en smeedt de weg naar buiten; verlossing geconstrueerd — de verslaafde, de verlorene, de veroordeelde, door het vuur heen gedragen naar de overkant.","curse":"Een ziel die niet gered wil worden → kan niet loslaten; verlost verder dan de ander toestaat; de verlosser wiens waarde afhangt van de drenkelingen, en die daarom — stilletjes — de vloed nodig heeft."},
  MAGICIAN_EXPLORER: {"gift":"Transformatie als paden banen: opent routes door wat iedereen onbegaanbaar noemde — industrieën, ideeën, wildernissen; achter hen liggen wegen waar muren stonden.","curse":"Een gebaand pad dat institutie wordt → minachting voor de kolonisten; ontgint dwangmatig nieuwe grond, eert niets wat op de oude grond gebouwd is, ook wat ze zelf bouwden niet."},
  MAGICIAN_HERO: {"gift":"Belichaamde visionaire wil: herschrijft de interface van de wereld EN drukt die herschrijving door de weerstand heen; paradigmaverschuivingen afgeleverd, niet alleen ontworpen.","curse":"Het onwrikbare — de dood, andermans wil → grootheidswaan of instorting bij absoluut controleverlies; de alchemie die geen lood kan accepteren dat ervoor kiest lood te blijven."},
  MAGICIAN_INNOCENT: {"gift":"Transformatie gevoed door zuiverheid: brandt de oude wereld optimistisch tot as en smeedt iets beters; de katalysator wiens geloof in het nieuwe ieders activeringsenergie verlaagt.","curse":"Nobele creaties misbruikt → de hoge stresstolerantie knapt; het vuur dat de verandering bracht keert zich tegen het geloof van de maker; de chemie van de hoop vergiftigd door het eerste verraad."},
  MAGICIAN_JUDGE: {"gift":"Transformatie met een kasboek: berekent wat elke verandering kost en wie ervoor betaalt; macht uitgeoefend met de bonnetjes erbij; de afrekening die niemand kan betwisten.","curse":"Een onaflosbare schuld ontdekt → de berekenaar wordt incasseerder; genade heeft geen cel in de spreadsheet; rekeningen zo precies vereffend dat de relatie failliet gaat."},
  MAGICIAN_LOVER: {"gift":"Transformatie via het hart: bedrijft alchemie op relaties en smeedt verdriet en haat om tot echte verbinding en liefde; de heler van wat er TUSSEN mensen gebeurt.","curse":"Emotionele afwijzing → diepe onzekerheid; loopt het risico de ander te sturen; charme die een hart regisseert is manipulatie in ceremonieel gewaad."},
  MAGICIAN_OUTLAW: {"gift":"Werkelijkheid gebogen door het narratief te grijpen: stapt midden in het verhaal en geeft het een draai; de hoofdrolspeler wiens lef de wereld dwingt zich om hen heen te herschikken.","curse":"Een verhaal zonder rol voor hen → saboteert andere hoofdrollen; het leven als plot dat om hen moet draaien; bondgenoten teruggebracht tot bijrollen tot de hele cast opstapt."},
  MAGICIAN_RULER: {"gift":"Magie ontmoet structuur: leest de verborgen variabelen van de tijdlijn en giet ze in stabiele, profetische systemen; de blauwdruk die al klopte vóór zijn tijd en zijn tijd overleefde.","curse":"Chaos van buiten die de blauwdruk bedreigt → forceert de werkelijkheid zonder empathie; mensen worden getallen in de vergelijking; het ontwerp verdedigd tegen de eigen gebruikers."},
  MAGICIAN_SAGE: {"gift":"Transformatie door onthechting: stapt buiten de dagelijkse werkelijkheid om het diepste mechanisme te doorgronden; keert terug met die ene ingreep die alles verandert.","curse":"Vage variabelen → verliest het contact met het lijf; onbegrepen, trekt zich terug in de toren; het geneesmiddel ontdekt en nooit afgeleverd omdat de oppervlakte hem te min was."},
  MAGICIAN_TRICKSTER: {"gift":"Buigt de werkelijkheid met een spreuk en een lach — en het werkt; transformatie zo charmant dat de wereld meewerkt voordat ze merkt dat ze veranderd is.","curse":"Tot het niet meer werkt; de situatie waar ze zich niet uit kunnen toveren wordt de leraar — en de leerling verschijnt woedend op de les."},
  OUTLAW_ARTIST: {"gift":"Opstand als rauwe expressie: drie akkoorden en de waarheid; de scene, de zine, het lawaai dat wie nooit gehoord wordt een geluid geeft en de gepolijste leugen een probleem.","curse":"Opgeslokt door de mainstream → woede op de machine die nu de woede verkoopt; authenticiteit bewaakt tot de scene zichzelf opvreet; volume verward met eerlijkheid."},
  OUTLAW_CAREGIVER: {"gift":"Opstand puur gedreven door empathie: vecht uitsluitend om onderdrukten en gemarginaliseerden te bevrijden; kracht die er volledig is voor de deur die voor een ander van het slot gaat.","curse":"Compassiemoeheid → draagt de pijn van de wereld tot aan de burn-out; en de eigen ketens van de bevrijder — waar geen menigte voor juicht — roesten ongebroken door."},
  OUTLAW_EXPLORER: {"gift":"Opstand in beweging: leeft volledig buiten de systemen; de vogelvrije wiens bestaan buiten de muren bewijst dat de muren optioneel zijn; vrijheid voorgeleefd, niet bepleit.","curse":"Ballingschap als identiteit → hoort uit principe nergens bij; het daarbuiten wordt zelf een kooi; vrij van alles, voor niets."},
  OUTLAW_HERO: {"gift":"Gedisciplineerde kracht zonder meester: handelt vanuit pure overtuiging; de ronin wiens code de dood overleefde van elke instelling die haar ooit onderdak bood.","curse":"Moreel verraad → losgeslagen; en het blijvende risico: ziet iedereen die de code niet haalt als vijand, terwijl sommigen gewoon hetzelfde gevecht voeren met minder kracht."},
  OUTLAW_INNOCENT: {"gift":"Opstand met schone handen: weigert de corrupte orde uit oprecht geloof in een betere; de idealist wiens onkreukbaarheid de cynici uit schaamte in beweging brengt.","curse":"Het ideaal gecompromitteerd door bondgenoten → purisme; splijt elke beweging bij negentig procent overeenstemming; het volmaakte als wapen gehanteerd tegen het goede."},
  OUTLAW_JUDGE: {"gift":"Principiële oppositie: het ingebouwde tegenwicht; blokkeert de consensus precies waar die een onrecht wegmoffelt; tegenspraak als openbare dienst.","curse":"Instemming, waar dan ook → argwaan; spreekt tegen uit reflex; de dwarsligger wiens 'nee' geen informatie meer draagt, omdat het nog nooit één keer ja zei."},
  OUTLAW_LOVER: {"gift":"De vonk in de menigte: maakt van een persoonlijke grief een gedeeld vuur; de aanstichter wiens passie de schuchteren moedig maakt en de versnipperden één.","curse":"Een menigte die afkoelt → provoceert om de hitte erin te houden; ontsteekt conflicten om het gevoel van de vlam; de brandstichter die het vuur meer mist dan de zaak."},
  OUTLAW_MAGICIAN: {"gift":"Ontwrichting versterkt door hefboomwerking: bestormt niet alleen het paleis maar legt de bedrading opnieuw aan; de revolutie gepland als een paradigmaverschuiving — timing, symbolen, structuren klaar voor de ochtend erna.","curse":"Compromis van bondgenoten → hoogverraad; de geconstrueerde opstand wordt het bezit van de constructeur; zuivert de revolutie om het ontwerp ervan te beschermen."},
  OUTLAW_RULER: {"gift":"Opstand die het centrum grijpt: dient geen verzoekschrift in bij de corrupte kroon, maar neemt haar; de troonrover wiens staatsgreep de verrotting vervangt door iets dat werkelijk bestuurt.","curse":"De veroverde troon → wordt wat het omverwierp; bewaakt de nieuwe kroon met de methoden van de oude; de revolutie die eindigde op de dag dat ze won."},
  OUTLAW_SAGE: {"gift":"Opstand toegepast op dogma: ontmantelt valse afgoden, dode religies, maatschappelijke illusies met chirurgische argumentatie; de hamer die tegelijk een bewijs is.","curse":"Overal intellectuele luiheid → extreem cynisme; isoleert zich; slaat door de valse afgoden heen tot in de dragende overtuigingen waarin mensen werkelijk leven."},
  OUTLAW_TRICKSTER: {"gift":"De absolute ontwrichter met een feilloos vizier: vrijheidsdrang plus salience-blik; breekt precies de dragende leugen en laat de rest staan.","curse":"Overal systeemcorruptie → oorlogsmodus als thuis; de woede slaat over op alles; vernietigt alles wat nog staat, ook de ochtend die een bouwer nodig had."},
  RULER_ARTIST: {"gift":"Het rijk als ontwerp: leiderschap dat niet alleen orde vormgeeft maar BETEKENIS — instituties met een esthetiek, structuren waar mensen bij willen horen.","curse":"Lelijkheid of compromis die het ontwerp wordt opgedrongen → minachting voor de bewoners; het rijk wordt een galerie waarin leven een schending van het concept is."},
  RULER_CAREGIVER: {"gift":"Macht als voorziening, tot systeem gemaakt: bouwt de veilige haven op grote schaal — de heerser wiens rijk een schuilplaats is, wiens begroting een daad van zorg is.","curse":"Afhankelijkheid of geëiste opoffering → verstikking; voorziet zo volledig dat niemand meer zelf mag staan; controle uitgeoefend via wat er gegeven wordt."},
  RULER_EXPLORER: {"gift":"Structuur ontmoet het grensgebied: smeedt onontgonnen terrein om tot werkende, winstgevende systemen; de eerste die bouwt waar anderen nog rondzwerven.","curse":"Marktfalen of een grensgebied dat dichtgaat → ambitie verzuurt tot hebzucht; mensen worden grondstof voor de volgende expansie; beweging aangezien voor richting."},
  RULER_HERO: {"gift":"Orde aan de punt van de speer: voert het bevel vanuit de voorste linie, wint terrein door wil en discipline; het rijk groeit omdat zijn heerser als eerste bloedt.","curse":"Zwakte of een verloren veldtocht → expansie wordt identiteit; verplettert autonomie, vat elke grens op als een belediging; kan niet stoppen omdat stoppen voelt als sterven."},
  RULER_INNOCENT: {"gift":"Stichtende kracht gevoed door vertrouwen: bouwt instituties op het geloof dat mensen het waard zijn om voor te bouwen; het handvest dat zijn auteur overleeft omdat het te goeder trouw is geschreven.","curse":"Verraad van het stichtende vertrouwen → de klap is totaal; ofwel naïef dubbel inzetten op een gebroken handvest, ofwel een verbitterde oprichter die voortaan elke handdruk doorlicht."},
  RULER_JUDGE: {"gift":"Soevereine structuur versmolten met de toetsing: een rijk dat niet alleen overeind staat, maar RECHTVAARDIG staat — elke regel gewogen voordat hij bindt; gezag waarbij mensen in beroep kunnen gaan.","curse":"Anarchie of een onrecht zonder beroepsmogelijkheid binnen het eigen systeem → de toetsing keert zich naar binnen en wordt genadeloos; regeert met het vonnis, vergeet te regeren met zorg."},
  RULER_LOVER: {"gift":"Heerschappij verwarmd door resonantie: de beschermheer wiens macht deuren opent voor wat hij liefheeft — kunst, mensen, belofte; gezag dat anderen laat opbloeien in zijn licht.","curse":"Ondankbaarheid of afstand van de begunstigden → beschermheerschap slaat om in eigendom; de geliefde protegé wordt een bezit, warmte wordt een schuld die moet worden afgelost."},
  RULER_MAGICIAN: {"gift":"Heerschappij via de hefboom: bestormt de muur niet maar bezit de poort; hervormt markten, wetten en loyaliteiten tot de wereld vanzelf bij de beoogde orde aankomt.","curse":"Het onverzettelijke — een wil die niet te kopen of te buigen is → grootheidswaan; de oppermeester die controle over het bord verwart met controle over de zielen van de spelers."},
  RULER_OUTLAW: {"gift":"Rebellie geïntegreerd in de hiërarchie: breekt het corrupte deel van het eigen systeem van binnenuit af en vervangt het terwijl het geheel blijft staan; leidt met natuurlijk gezag, niet met geërfde rang.","curse":"Bureaucratie of intern verraad → het eigen regels breken voelt niet langer als hervorming maar als hoogverraad; starre verdediging van de 'nieuwe orde' die geboren werd om open te blijven."},
  RULER_SAGE: {"gift":"Plato's ideaal via de patroonlezer: heerschappij gestuurd door begrip van de diepe structuur; beleid dat al decennia juist is voordat het populair wordt.","curse":"Irrationaliteit van de geregeerden → de toren sluit zich af; systemen die intellectueel foutloos zijn en emotioneel onbewoond; wijsheid verhardt tot dogma dat niet meer luistert."},
  RULER_TRICKSTER: {"gift":"Heersen aan de verborgen draad: leest bij elke speler de verraderlijke tic, stuurt het hof met gevatheid en timing; macht die nooit haar stem hoeft te verheffen omdat ze de eerste zet al deed.","curse":"Afgetroefd of ontmaskerd worden → controle verstrakt tot manipulatie; iedereen wordt een pop, en een heerser over poppen regeert over een leeg theater."},
  SAGE_ARTIST: {"gift":"Inzicht dat wordt opgeleverd: zet begrip om in werkende dingen — theorieën in gereedschap, patronen in producten; de ontwikkelaar wiens begrip compileert.","curse":"De elegante refactoring zonder eind → bouwen uitgesteld voor begrijpen; of begrijpen overgeslagen voor bouwen; het systeem eeuwig herschreven, nooit uitgebracht."},
  SAGE_CAREGIVER: {"gift":"Wijsheid die draagt: begeleidt leerlingen en dierbaren met een enorme intelligentie die nooit wordt ingezet om te overheersen; de mentor wiens grootste werken op eigen benen rondlopen.","curse":"Falen van de leerling → gedragen als eigen falen; en de stille afhankelijkheid: de groei van de leerling nodig hebben als zuurstof; wijsheid met een onzichtbaar touwtje eraan."},
  SAGE_EXPLORER: {"gift":"Begrip in beweging: één lange zoektocht naar waarheid, gevoed door elk nieuw terrein dat wordt betreden — grenzen, vakgebieden, disciplines overschreden en begrepen. Diepte die reisde voor haar breedte; een weten dat levend blijft doordat de zoektocht nooit wordt afgesloten.","curse":"Het archief als vesting → verzamelt begrip zoals anderen grondgebied verzamelen; de voetnoot perfect, de toepassing eeuwig in afwachting; geleerd over alles, veranderd door niets."},
  SAGE_HERO: {"gift":"Waarheidsvinding met gericht handelen: rust niet voordat verborgen patronen en onzichtbare motieven boven water komen; begrip dat opstaat van het bureau en aanklopt bij deuren.","curse":"Onopgeloste afwijkingen → obsessief controleren, paranoïde voyeurisme; de zaak die niet dicht kan, sluit in plaats daarvan de speurder op."},
  SAGE_INNOCENT: {"gift":"Het hoogtepunt van innerlijke reflectie: stapt buiten het zelf, vrij van vooringenomenheid; helderheid zo volledig dat ze geen discussies meer hoeft te winnen; aanwezigheid die ruimtes stil maakt.","curse":"Materiële begrenzing → dissociatie; de verlichting die loszweeft van de afwas, de file, het gesprek zonder richting — en daarmee van het leven."},
  SAGE_JUDGE: {"gift":"Gedisciplineerde twijfel: toetst elke bewering aan bewijs voordat die in huis mag wonen; de skepticus wiens 'bewijs het maar' de hele gemeenschap eerlijk houdt.","curse":"Twijfel zonder bodem → vreet alles aan, ook vertrouwen, liefde en de eigen zintuigen; de skepticus die bewijs eiste voor de zonsopgang en die miste."},
  SAGE_LOVER: {"gift":"Onderwijzen door toewijding: wijsheid doorgegeven binnen een band zo warm dat de les niet los te zien is van de liefde; leerlingen die de stof leerden en betere mensen werden.","curse":"De toewijding die opzwelt → het voetstuk; volgelingen in plaats van leerlingen; de goeroe die begon met waarheid uitleggen en eindigde met zekerheid opvoeren voor een publiek dat was opgehouden met vragen stellen."},
  SAGE_MAGICIAN: {"gift":"Wijsheid in stilte in de praktijk gebracht: bouwt de structuren, riten en normen die de wereld vormen, zonder ze te signeren; invloed uitgeoefend als architectuur, niet als aankondiging.","curse":"Geheimhouding als voorliefde → de verborgen hand krijgt een voorkeur voor het verbergen; kennis opgepot als rang; de loge die begon als school en verkalkte tot een deurbeleid."},
  SAGE_OUTLAW: {"gift":"Bewuste radicale afzondering: koppelt zich los van de collectieve ruis om het werkelijke signaal te horen; keert uit de stilte terug met wat geen enkele vergadering ooit had opgeleverd.","curse":"Gedwongen interactie → extreem energielek; heilig alleenzijn slaat om in mensenhaat; de deur zo lang gegrendeld dat het kloppen ophoudt — en gemist wordt."},
  SAGE_RULER: {"gift":"Filosofie toegepast op externe orde: structureert ruwe theorie tot heldere, onweerlegbare systemen; de objectieve adviseur wiens analyse het draaiboek wordt.","curse":"Ambiguïteit → analyseverlamming; geen besluit overleeft de volgende variabele; en het systeem dat geen ruimte laat voor het irrationele, bestuurt geen echte mensen."},
  SAGE_TRICKSTER: {"gift":"Spel op het niveau van ideeën: bouwt en breekt conceptuele kaders voor de sport; de theoreticus wiens gedachte-experimenten onthullen welke zekerheden al die tijd meubilair waren.","curse":"Theorie als ontwijking → alles geherkaderd, niets geconcludeerd; het elegante model verkozen boven de ongemakkelijke meting; spelletjes met kaders terwijl het huis afbrandt."},
  TRICKSTER_ARTIST: {"gift":"Waarheid via imitatie: vangt een persoon, een type, een tijdperk in één gebaar; de imitatie zo precies dat ze tegelijk werkt als kritiek, portret en geschenk.","curse":"Altijd alleen de spiegel → het eigen gezicht van de imitator ongebruikt; gevierd om honderd stemmen, stil in die ene die van henzelf is."},
  TRICKSTER_CAREGIVER: {"gift":"Adaptieve zorg door nabootsing: wordt wat ieder mens nodig heeft — de grappenmaker voor wie rouwt, de stille voor wie overweldigd is; camouflage in dienst van troost.","curse":"Aanpassen als standaard → de eigen kleur vergeten; peilt elk gezelschap zo automatisch dat geen gezelschap hen ooit peilt; behulpzaam in elke gedaante, gekend in geen enkele."},
  TRICKSTER_EXPLORER: {"gift":"De wereld herlezen als routes: ziet doorgang waar anderen muren zien — erover, eronder, erdoor; obstakels op volle snelheid omgezet in uitnodigingen; improvisatie als lichamelijke filosofie.","curse":"Stilstand → ondraaglijk; stroomt om elk obstakel heen, ook om de obstakels die een confrontatie verdienden; een leven vol perfecte ontwijkingen en geen enkele landing."},
  TRICKSTER_HERO: {"gift":"Uitmuntendheid met een grijns: wint de wedstrijd en laat het eruitzien als spel; de aas wiens lichtheid niet de afwezigheid van discipline is, maar haar eindvorm.","curse":"De reeks die eindigt → de grijns is dragend; identiteit vastgesoldeerd aan moeiteloosheid; waagt liever geen poging dan zichtbaar te proberen en te falen."},
  TRICKSTER_INNOCENT: {"gift":"Plezier genomen zonder toestemming: leent de wereld voor de lol; de joyride die niemand kwaad doet en iedereen eraan herinnert dat de regels nooit waren waar het in het leven om ging.","curse":"De kick die moet escaleren → roekeloosheid; plezier dat gestolen moet zijn om mee te tellen; de joyrider die niet kan genieten van wat zomaar gegeven wordt, ook niet van liefde."},
  TRICKSTER_JUDGE: {"gift":"Waarheid via tegenspraak: bepleit het onverdedigbare zo briljant dat de zaal eindelijk onderzoekt wat ze geloofde; de advocaat van de duivel als het immuunsysteem van het oordeel.","curse":"De rol die de persoon opslokt → tegendraads tot in het merg; wint elke discussie en houdt er geen enkel standpunt op na; een geest die alles kan verdedigen en nergens voor staat."},
  TRICKSTER_LOVER: {"gift":"Verlangen ontwapend door spel: verleiding die eerlijk toegeeft een spel te zijn en gul is in het spelen; maakt mensen wakker voor hun eigen magnetisme.","curse":"Het spel verkozen boven de prijs → verzamelt beginmomenten; als iemand blijft, vlucht de verleider voor het einde van de jacht; charme als slotgracht rond het hart."},
  TRICKSTER_MAGICIAN: {"gift":"Voortdurende wisseling van vorm, identiteit, perspectief als instrument: speelt bewust met het weefsel van de waarneming; laat anderen zien dat hun vaste zelf altijd al een kostuumkeuze was.","curse":"Geen vaste vorm → kan meedogenloos manipulatief worden of in een identiteitsleegte vallen; de gedaanteverwisselaar die de zwaartekracht uiteindelijk te pakken krijgt: elke vorm was echt, en geen enkele was thuis."},
  TRICKSTER_OUTLAW: {"gift":"Waarheid als manier van bewegen: de dwaas zegt het onzegbare niet — hij beloopt het. Elke opkomst, elk gebaar en elk vertrek ongefilterd; een wezen zo vrij dat niemand het kan plaatsen, kopen of zich erop kan voorbereiden. Waar hij loopt, moet de schijn zich rond hem herschikken.","curse":"Het lopen ingelijfd als vermaak — de orde applaudisseert en er beweegt niets → de tred wordt het masker; de vrije stap opgevoerd lang nadat hij niet meer vrij was; de dwaas die overal heen liep behalve naar binnen — de enige weg die hem opvrat."},
  TRICKSTER_RULER: {"gift":"Ziet elke structuur als iets wat gebouwd is: de kaders rond de macht zijn constructies, en hij kan het timmerwerk lezen. Waar anderen muren zien, ziet hij hoe ze in elkaar zijn gezet — het kader rond de troon was nooit dragend, en nu heeft iedereen het gezien.","curse":"Geen orde meer over die het ontmaskeren waard is → niets kan hem nog houden; erbij horen komt over als gevangenschap; wie door elke structuur heen keek, kan door geen enkele meer worden vastgehouden, ook niet door de structuren die een leven bij elkaar houden."},
  TRICKSTER_SAGE: {"gift":"Ontwrichting via het raadsel: verpakt de diepste observaties in puzzels die mensen dwingen zich een weg naar de waarheid te DENKEN; het verdiende antwoord landt dieper dan het gegeven antwoord.","curse":"Helderheid uit principe geweigerd → ondoorgrondelijkheid als superioriteit; raadsels zonder antwoord, gesteld om onaantastbaar te blijven; de raadselmeester die niemand oplost omdat er niets verborgen was."},
};

const EXTENSION_CELLS_EN = {
  ARTIST_CAREGIVER: {"gift":"Creation for connection: translates raw lonely emotion into stories that heal the group; the teller whose tales are how the community remembers it is one.","curse":"Group disharmony → avoids the hard artistic truth to keep the peace and the audience; the story sweetened until it no longer nourishes."},
  ARTIST_EXPLORER: {"gift":"Creation tied to discovery: looks decades ahead, predicts the coming shape, illuminates the future so vividly others start building toward it early.","curse":"Analysis-paralysis in the now → heavy stress when the present demands presence; the visionary who lives at a coordinate no calendar can reach."},
  ARTIST_HERO: {"gift":"Creation meets iron will: actively re-forges the world; design driven straight through material resistance; the smith who makes the tools history is then made with.","curse":"Innovation-block → aggressive emotion-suppression, extreme tunnel-vision; sacrifices self and love to the forge; the maker fed piece by piece into his own machine."},
  ARTIST_INNOCENT: {"gift":"Makes from pure clarity: the work arrives rather than being built — no irony, no calculation between eye and hand; a purity training cannot manufacture. The world calls it talent; talent was never what it was.","curse":"The pure proven ordinary — the flow claimed as property, performed as skill → the channel silts; forms forced where they once arrived; the source left performing its own memory."},
  ARTIST_JUDGE: {"gift":"The merciful knife: sees what a work wants to be and cuts away everything else; the editor whose deletions are a form of faith in the maker.","curse":"The cut turned on everything → nothing survives revision; perfection as a paper-shredder; edits the life as ruthlessly as the page until neither has a draft left standing."},
  ARTIST_LOVER: {"gift":"Art as courtship of the world: sings feeling directly to its subject; the troubadour whose work closes the distance between hearts in real time, in the room.","curse":"The applause standing in for the beloved → serenades everyone, reaches no one; performs longing so beautifully the actual longing never gets a turn to speak plainly."},
  ARTIST_MAGICIAN: {"gift":"Craft as transformation: knows the material's secret grain and works WITH it; the craftsman whose objects hold because he understood what the material itself wanted to become.","curse":"Mass-production and shortcuts everywhere → bitterness; the standard raised into a priesthood; perfect chairs made for a world dismissed as unworthy to sit."},
  ARTIST_OUTLAW: {"gift":"Creation as detonation: makes the work the polite world cannot un-see; the provocateur whose images do in one glance what a hundred essays argued.","curse":"Shock as the only register → provokes past the point; the detonation without the payload; scandal collected while the message starves."},
  ARTIST_RULER: {"gift":"Creative flow captured in brilliant structures: designs systems and buildings both beautiful AND usable; form that serves living as faithfully as it serves the eye.","curse":"People disobeying the perfect blueprint → merciless; the aesthetic defended against its inhabitants; architecture sliding into tyranny one 'don't touch' at a time."},
  ARTIST_SAGE: {"gift":"The peak of the creative axis: designs entire subjective universes and new paradigms of existence; worlds so coherent people move in and live by their physics.","curse":"Reality's limits → refusal to compromise with the physical world; God-complex on setback; and the inhabitants of the made world treated as characters, not people."},
  ARTIST_TRICKSTER: {"gift":"Truth delivered in symbol: speaks what is coming in images the present can hold; the oracle whose riddles are mercy — the future dosed so it can be received.","curse":"Being believed too literally or not at all → speaks ever more obliquely; hides behind ambiguity; the oracle who was never once caught being plainly wrong because never once plainly anything."},
  CAREGIVER_ARTIST: {"gift":"Restoration as an art: mends what is damaged — objects, houses, people — with such attention that the repair becomes part of the beauty; kintsugi as a way of caring.","curse":"The unrestorable → cannot accept that some things stay broken; keeps mending past consent; or grieves every crack as a personal failing of care."},
  CAREGIVER_EXPLORER: {"gift":"Care in motion: accompanies another's journey step for step — the companion on the pilgrimage who carries the pack when the road gets steep.","curse":"The journey's end → does not know how to stop walking beside; either finds a new pilgrim immediately or stands lost at the destination that was never theirs."},
  CAREGIVER_HERO: {"gift":"Vigilant protection: stands the watch no one sees, absorbs what would have reached the vulnerable; safety produced nightly by someone who never mentions it.","curse":"Never off duty → who never takes off the armour forgets how the sun feels; the watch becomes the identity; protects everyone from everything except their own absence."},
  CAREGIVER_INNOCENT: {"gift":"Unconditional belief as care: sees the good in a person before they can see it themselves, and tends it faithfully until it takes root.","curse":"The believed-in person failing → the faith doubles instead of adjusting; devotion to the potential blinds to the actual; loyal to who someone could be, absent from who they are."},
  CAREGIVER_JUDGE: {"gift":"Protection with a verdict in its hand: defends the vulnerable by naming the wrong out loud; care that testifies, files, wins.","curse":"A case lost → carries the client's fate as a personal failure; or defends so fiercely that the protected person's own voice never gets heard in court."},
  CAREGIVER_LOVER: {"gift":"Service fused with deep intimacy: heals not at arm's length but skin-close; the safe haven where being truly seen is itself the medicine.","curse":"Emotional disharmony → identity rests on the healing; when the patient recovers or resists, the healer's ground vanishes; care shades into codependent keeping."},
  CAREGIVER_MAGICIAN: {"gift":"Guardianship by design: does not fight the threat at the door but builds the door; wards, protocols, provisions — safety engineered so completely it looks like luck.","curse":"Control mistaken for care → the ward becomes a cell; keeps what it protects; the warden who cannot tell anymore whether the locks face outward or inward."},
  CAREGIVER_OUTLAW: {"gift":"Care that knows when not to intervene: holds a hand open instead of forcing the healing; grows people the way a gardener grows — conditions, not commands.","curse":"Watching a destructive pattern repeat → the urge to break it for them; when restrained too long, either explodes into rescue or hardens into detachment."},
  CAREGIVER_RULER: {"gift":"Compassion as an organised force: builds the household, the institution, the lineage that protects at scale; providence with a spine of governance.","curse":"Anarchy or ingratitude → smothering; provision becomes leverage; the family held so safely no one in it is allowed to grow up."},
  CAREGIVER_SAGE: {"gift":"Care from psychological insight: sees the mechanism under the suffering; a self-replenishing source because understanding does not burn out the way absorbing does.","curse":"Over-analysis → not all pain has a findable cause; the search for the why becomes a way of not sitting with the what; the patient explained, not accompanied."},
  CAREGIVER_TRICKSTER: {"gift":"The emotional radar in service of care: feels the room's unspoken weather, reaches the person everyone else missed; comfort delivered before the tears.","curse":"Absorbing what is read → carries every room home; boundaries dissolve into the other's state; the empath drowning in signal that was never theirs to hold."},
  EXPLORER_ARTIST: {"gift":"The road turned into song: gathers the world's stories and carries them between places; the bard whose travel IS the archive, whose telling makes strangers kin.","curse":"No audience, no hearth → the songs sour; performs the journey instead of living it; a life narrated so continuously it was never quite attended."},
  EXPLORER_CAREGIVER: {"gift":"Trailfinding as service: goes ahead not for the glory of first but to make the way passable for those who follow; marks the path, carries the weak across.","curse":"No one following → purposelessness; or refuses to let the followers ever lead; the pathfinder who needs the lost more than the lost need the path."},
  EXPLORER_HERO: {"gift":"Proven resilience: survives everything — the storm, the doldrums, the loss of the cargo; endurance so deep it has become a kind of navigation.","curse":"Endless survival → the question is not whether they make it but whether they ever arrive somewhere that does not require surviving; rest read as surrender."},
  EXPLORER_INNOCENT: {"gift":"Mapping with a compass of trust: explores not to escape but to chart; brings back objective new truths AND the faith that the crossing is worth it.","curse":"Stagnation → intolerable; calculates escape-variants from any stillness; the map grows while the home-coordinate stays forever blank."},
  EXPLORER_JUDGE: {"gift":"Exploration with a measuring line: surveys the unknown precisely — what is here, what it is worth, where the boundary honestly runs; the vanguard whose reports hold up.","curse":"Disputed ground → rigid; the surveyor who trusts the instrument over the inhabitant; borders drawn correct and cruel."},
  EXPLORER_LOVER: {"gift":"Wonder as connection: explores upward and outward and takes someone's hand while doing it; the night sky, the far coast, the unknown — offered as a shared astonishment.","curse":"A companion who stops looking up → drifts to the next pair of eyes; loves the wondering-together more than the together; horizons collected, harbours declined."},
  EXPLORER_MAGICIAN: {"gift":"Mastery of the unrooted life: makes a home of movement itself; resources conjured anywhere, belonging carried inside; free because nothing external is load-bearing.","curse":"An offered root → panic dressed as principle; transforms every 'stay' into a reason to go; the nomad whose freedom is a wall with wheels."},
  EXPLORER_OUTLAW: {"gift":"Restless invention with teeth: does not just see the next thing but breaks the current thing open to build it; innovation as productive rebellion.","curse":"Abandonment of the made → a trail of brilliant orphans; the world lacks not inventions but people who stay with their inventions past the honeymoon."},
  EXPLORER_RULER: {"gift":"Exploration through people, organised: builds the network as infrastructure — introductions, alliances, routes between worlds; the connector whose map is made of names.","curse":"Social exclusion or a static circle → the engine stalls; collects contacts past the point of contact; a friend to all, anchored to none."},
  EXPLORER_SAGE: {"gift":"The philosophy of the road: travels to understand, not to collect; every border crossed becomes a concept tested; wisdom with dust on its boots.","curse":"Disembodiment → theory detached from ground; the philosopher who has been everywhere and touched nothing; insight that never lands because it never stays."},
  EXPLORER_TRICKSTER: {"gift":"The scout who reads the trick of the land: sees the ambush, the shortcut, the tell in the terrain; travels light, arrives first, laughs at the map's mistakes.","curse":"Loss of the own discipline-anchor → drifts; cleverness without a mission scouts in circles; the first to arrive everywhere and commit nowhere."},
  HERO_ARTIST: {"gift":"Combat as craft: the duel fought beautifully — precision, style, honour; wins in a way that even the defeated call masterful.","curse":"An ugly, necessary fight → refuses it; aesthetics over outcome; the duelist who would rather lose exquisitely than win gracelessly, and calls it principle."},
  HERO_CAREGIVER: {"gift":"Combat-strength for compassion: the human shield; catches every blow for the vulnerable and endures impossible hardship to keep others whole.","curse":"Other's suffering unpreventable → the shield that never asks for help breaks first; protection given as a debt no one may ever repay."},
  HERO_EXPLORER: {"gift":"The impossible attempted with discipline: trains for years to cross what no one crossed; heroism aimed at the frontier itself rather than an enemy.","curse":"No launch window → the drive corrodes inward; earth feels like defeat; a life calibrated for the exceptional that cannot metabolise an ordinary Tuesday."},
  HERO_INNOCENT: {"gift":"Will in service of a shining cause: fights for the good with total conviction; the crusade that moves mountains because its soldier genuinely believes.","curse":"The cause revealed impure → cannot afford to see it; doubles down; the crusader who burns the village to save the story he tells about himself."},
  HERO_JUDGE: {"gift":"Force under vows: fights only for what has been weighed and found just; the warrior whose restraint is as feared as his blade; power that keeps its oath.","curse":"The code betrayed by its own church → crisis; either crusades harder to silence the doubt or breaks entirely; righteousness calcified into the very thing the vow opposed."},
  HERO_LOVER: {"gift":"Chivalric devotion: strength placed wholly at the service of one beloved — the vow, the favour, the standing-between; love expressed as guarding presence.","curse":"The beloved not needing rescue → purposeless; invents dragons; the knight who loves the rescuing more than the person, and calls the pedestal devotion."},
  HERO_MAGICIAN: {"gift":"Pure heroic will at its zenith: the performance that becomes a story others live by; resilience so complete it transforms what people believe is possible.","curse":"The jug goes to the well until it breaks — and they WERE the jug; the legend maintained after the body filed its objection; applause mistaken for fuel."},
  HERO_OUTLAW: {"gift":"Force unbound: strikes where slow armies cannot; takes what fortified injustice hoarded; the raid as surgery on a rotten order.","curse":"No worthy target → the raiding becomes the point; plunder without a cause; strength that, unemployed by meaning, starts billing the innocent."},
  HERO_RULER: {"gift":"Conquest that holds: wins the ground AND organises it; force converted into standing order; the campaign whose ending is a functioning peace.","curse":"A realm at rest → restlessness; peace read as decay; the conqueror who must keep finding walls because he only knows himself mid-siege."},
  HERO_SAGE: {"gift":"Execution fed by deep pattern: foresees the entire campaign, wins before the first move; force multiplied by comprehension.","curse":"Worst-case projection → paralysis by the modelled catastrophe; and the one cost every model omitted — the strategist himself, spent as a pawn."},
  HERO_TRICKSTER: {"gift":"The contest won in shadow: infiltrates, reads, misdirects; the agent whose greatest victories are the battles that never had to happen.","curse":"No handler, no mission → identity dissolves into covers; the spy who has been everyone so long that 'me' is the one legend never built."},
  INNOCENT_ARTIST: {"gift":"The utopia made visible: paints, writes, builds the better world so vividly that others start walking toward it; hope with a picture attached.","curse":"Reality refusing the design → despair or denial; the utopian who loves the painting more than the people it was painted for."},
  INNOCENT_CAREGIVER: {"gift":"Paradise aimed at the other: unconditional, joyful help for the stranger; forgiveness and provision given without a ledger.","curse":"Cynical reality intruding → flight into denial; helps in order not to feel the dark; goodness as an anaesthetic against the world's actual weight."},
  INNOCENT_EXPLORER: {"gift":"Embodied hope in motion: carries fundamental trust into cynical places and leaves them lighter; the absolute light that travels.","curse":"Accusation of sin → violent inner reaction; the sainthood defended harder than the goodness lived; purity as a fortress against being seen whole."},
  INNOCENT_HERO: {"gift":"Optimism with hands and boots: believes the unknown holds something good AND goes first to prove it; the settlement that exists because someone hopeful was also relentless.","curse":"Loss of momentum → burnout; the vision-fed stress-tolerance collapses at standstill; fears the pause more than the wilderness."},
  INNOCENT_JUDGE: {"gift":"Tradition with a standard: keeps not everything old but everything TRUE in the old; the customs curated, the values audited, the heritage that deserves its keeping.","curse":"The new arriving → judges before understanding; the standard fossilises; defends the letter of a tradition whose spirit already left the building."},
  INNOCENT_LOVER: {"gift":"Disarming warmth: the presence that makes rooms kinder; loved easily and loving easily; innocence that melts armour nobody knew they wore.","curse":"First betrayal → the sweetness curdles or performs; keeps being adorable to stay safe; the darling everyone adores and no one has actually met."},
  INNOCENT_MAGICIAN: {"gift":"Hope that transforms on contact: enters a stuck situation and things begin to move — not by force but by the sheer chemistry of believing change is possible.","curse":"The reaction failing to start → doubts the own goodness rather than the conditions; keeps throwing light into inert rooms until the source runs dry."},
  INNOCENT_OUTLAW: {"gift":"The torch in dark places: brings uncompromised hope into broken systems; the one who walks into the protest, the ward, the ruin, still believing — and the belief is contagious.","curse":"Darkness that will not lift → the torch guttered; either burns out from carrying light where none returns, or denies the dark so hard the testimony stops being honest."},
  INNOCENT_RULER: {"gift":"Hope anchored in tradition: keeps the values, the rituals, the field where the flock is safe; continuity as a form of love.","curse":"Unpredictability → terror beneath the calm; guards the pasture so rigidly the grass dies; keeping mistaken for holding still."},
  INNOCENT_SAGE: {"gift":"Pure hope wed to pattern-sight: designs and holds the vision of the perfect world or theory; faith with an architecture.","curse":"Broken ideals → extreme sensitivity to the world's failure to match the flawless design; grief for a utopia mistaken for a promise."},
  INNOCENT_TRICKSTER: {"gift":"Purity plus play: refuses the heaviness of rules without malice; the boundary crossed with a laugh that shows everyone the fence was imaginary.","curse":"Pragmatic confinement → violent stress when the bubble is punctured; flees into whimsy; freedom performed harder the less it is felt."},
  JUDGE_ARTIST: {"gift":"Judgement with an eye: values what others overlook, prices the priceless honestly; the verdict that tells a maker not only what is wrong but what is RARE.","curse":"Kitsch rewarded, mastery ignored → contempt; the appraisal turns to gatekeeping; forgets that taste is a lens, and starts wielding it as a law."},
  JUDGE_CAREGIVER: {"gift":"Icy objectivity warmed by care: restores broken relationships by weighing both sides AND holding both; the verdict people can live with because both were seen.","curse":"Emotional distance → suspends the objective truth to keep the peace; the mediation that heals the room and quietly buries the wrong."},
  JUDGE_EXPLORER: {"gift":"The audit as expedition: follows the money, the paper, the anomaly across any terrain; findings no one can dispute because every step is walked and logged.","curse":"A trail that ends nowhere → cannot close the file; keeps travelling through ledgers long after the answer stopped mattering; verification as a way of never arriving."},
  JUDGE_HERO: {"gift":"Justice with hands: does not file the wrong away but goes and ends it; protects the oppressed with a will that corruption learns to fear.","curse":"Powerlessness → vigilantism; cruel means for right ends; the avenger who no longer tests the own verdict has become a weapon that thinks it is a court."},
  JUDGE_INNOCENT: {"gift":"Moral weighing in service of the new: the ethical gatekeeper who tests ideas without killing them; purity as a standard, hope as the reason for the standard.","curse":"Stagnation or corruption of the pure → paralysing perfectionism; no candidate ever passes; the gate becomes a wall and the examiner its prisoner."},
  JUDGE_LOVER: {"gift":"Reconciliation through felt fairness: reads the hurt under both positions and speaks it aloud; the settlement that lands because both hearts heard themselves in it.","curse":"A rift that resonance cannot bridge → takes the failure personally; keeps mending what wants to end; peace pursued past the point where the truth was the kinder outcome."},
  JUDGE_MAGICIAN: {"gift":"Enforcement by design: builds the mechanism that makes the wrong impossible rather than punished; consequence engineered into the system itself.","curse":"A loophole found → the machinery tightens until it grinds the innocent too; enforcement so total that mercy has no interface left to enter through."},
  JUDGE_OUTLAW: {"gift":"Objective law wielding disruption: blows corrupt systems open to reveal the truth; the one insider willing to detonate their own position for the record.","curse":"Top-level hypocrisy → violent stress-spike; the detonation becomes the identity; keeps blowing open what a quieter hand could have healed."},
  JUDGE_RULER: {"gift":"Impartial authority at system-scale: the verdict that binds because the structure behind it is sound; integrity enforced wall to wall.","curse":"System-errors → draconian; punishment without context; the arbiter who serves the code so purely that the case disappears behind it."},
  JUDGE_SAGE: {"gift":"Quality-control at the level of first principles: finds the hidden fallacy, the structural rot, the hypocrisy in the argument itself; the standard everyone secretly wants to pass.","curse":"Intellectual error left standing → obsession with what is wrong; cynical rumination; a mind so trained on flaws it can no longer see that something works."},
  JUDGE_TRICKSTER: {"gift":"Truth-finding by interrogation: reads the flinch, asks the one question the lie cannot survive; corruption exposed not with a bomb but with a mirror.","curse":"An answer that will not come → the questioning becomes the cruelty; suspects everyone, converts every conversation into an examination no one passes."},
  LOVER_ARTIST: {"gift":"Love that ignites making: the presence that turns another's talent incandescent; inspires not by demanding art but by being worth making it for.","curse":"The maker's gaze fading → identity collapse; exists only as reflected in the work of others; the muse who was never asked what she herself would create."},
  LOVER_CAREGIVER: {"gift":"The ultimate fusion grounded in care: not only feels the other completely but BUILDS around them; a bond that is both fire and shelter.","curse":"Perceived distance → clings by caretaking; makes itself indispensable to make itself unleaveable; love administered as service until the self is the missing person."},
  LOVER_EXPLORER: {"gift":"Love as pilgrimage: crosses any distance toward what sets it alight — a person, a place, a transcendence; passion with a compass.","curse":"The flame reached → circles, burns, cannot land or leave; mistakes the intensity of approach for the substance of arrival; wings traded for one bright night."},
  LOVER_HERO: {"gift":"Love with great intensity and devotion: pursues the bond, fights for it, shows up — the romance that is also a discipline.","curse":"Mistakes intensity for truth → manufactures storms to feel the love prove itself; cannot sit in the quiet where the real thing lives."},
  LOVER_INNOCENT: {"gift":"Devotion in its purest key: loves one thing wholly and without irony — a person, a craft, a faith; constancy that makes the loved thing MORE true.","curse":"The devoted-to proves unworthy → the world's colour drains; either denial that polishes the idol or a collapse of everything that was built on it."},
  LOVER_JUDGE: {"gift":"Love that gives its word: fidelity as a chosen verdict, the promise weighed before it is spoken and kept after everyone stopped watching.","curse":"Doubt about the other's vow → love turns into evidence-gathering; audits affection, keeps score; the betrothed becomes the accused."},
  LOVER_MAGICIAN: {"gift":"Enchantment in love: reads the hidden levers of longing and plays them like an instrument; makes the beloved's world larger, stranger, more alive.","curse":"Magnetism failing → insecurity turns the charm to steering; seduction becomes management of the other's feeling; the spell that, discovered, poisons everything it built."},
  LOVER_OUTLAW: {"gift":"Love unshackled: breaks the heavy social scripts around desire; brings uncomplicated joy where duty had bricked the windows shut; pleasure as honest rebellion.","curse":"Confinement sensed → flees into frivolity; the libertine who mistakes every depth for a cage and every cage for a reason to run; freedom that starves."},
  LOVER_RULER: {"gift":"Intimacy bound to order: builds the shared life like a realm — loyal, stable, provisioned; love as a fort with the door on the inside.","curse":"Instability of the frame → terror; when the rules of the relationship wobble, becomes emotionally rigid; defends the fort so hard the beloved starts living outside it."},
  LOVER_SAGE: {"gift":"Raw vulnerability translated with precision: emotion passed through understanding into words that make strangers feel known; the line that names what everyone carried.","curse":"Loss of inspiration → melancholy studied instead of lived; dissects the own heart for material until the feeling dies on the table."},
  LOVER_TRICKSTER: {"gift":"Love's ally with perfect timing: reads what two people cannot say to each other and builds the bridge with a joke; connection engineered through lightness.","curse":"Always the bridge, never the destination → hides the own longing behind the assist; the wingman who lands everyone home and walks back alone, laughing."},
  MAGICIAN_ARTIST: {"gift":"The change staged: transforms a room, an audience, a market by performance — the demonstration so compelling that seeing it IS being changed by it.","curse":"Applause as the metric → performs past the truth; the act polished until it replaces the work; achievement curated instead of earned."},
  MAGICIAN_CAREGIVER: {"gift":"Transformation FOR someone: descends into another's ruin and forges the way out; redemption engineered — the addict, the lost, the condemned, carried through the fire to the far side.","curse":"A soul that will not be saved → cannot release; redeems past consent; the redeemer whose worth depends on the drowning, and who therefore — quietly — needs the flood."},
  MAGICIAN_EXPLORER: {"gift":"Transformation as trailbreaking: opens routes through what everyone called impassable — industries, ideas, wildernesses; behind them, roads exist where walls were.","curse":"An opened trail institutionalised → contempt for the settlers; breaks new ground compulsively, honours nothing built on the old ground, including their own."},
  MAGICIAN_HERO: {"gift":"Visionary will embodied: rewrites the world's interface AND pushes the rewrite through resistance; paradigm-shifts delivered, not just designed.","curse":"The immovable — death, another's will → grandiosity or breakdown at absolute loss of control; the alchemy that cannot accept lead that chooses to stay lead."},
  MAGICIAN_INNOCENT: {"gift":"Transformation fed by purity: burns the old world optimistically to ash and forges better; the catalyst whose faith in the new lowers everyone's activation-energy.","curse":"Noble creations misused → the high stress-tolerance snaps; the fire that made the change turns on the maker's faith; hope's chemistry poisoned by its first betrayal."},
  MAGICIAN_JUDGE: {"gift":"Transformation with a ledger: computes what every change will cost and who will pay it; power exercised with the receipts attached; the reckoning nobody can dispute.","curse":"An unpayable debt discovered → the reckoner turns collector; mercy has no cell in the spreadsheet; accounts settled so precisely the relationship goes bankrupt."},
  MAGICIAN_LOVER: {"gift":"Transformation through the heart: performs alchemy on relationships, forging grief and hate into real connection and love; the healer of what happens BETWEEN people.","curse":"Emotional rejection → deep insecurity; risks steering the other; charm that manages a heart is manipulation wearing ceremony."},
  MAGICIAN_OUTLAW: {"gift":"Reality bent by seizing the narrative: steps into the centre of the story and turns it; the protagonist whose audacity makes the world reorganise around them.","curse":"A story that will not cast them → sabotages other leads; life as a plot that must centre them; allies reduced to supporting roles until the cast walks out."},
  MAGICIAN_RULER: {"gift":"Magic meets structure: reads the timeline's hidden variables and pours them into stable, prophetic systems; the blueprint that was right before its time and lasted past it.","curse":"External chaos endangering the blueprint → forces reality without empathy; people become numbers in the equation; the design defended against its own users."},
  MAGICIAN_SAGE: {"gift":"Transformation through detachment: steps outside daily reality to grasp the deepest mechanism; returns with the one intervention that changes everything.","curse":"Vague variables → loses body-contact; misunderstood, retreats into the tower; the cure discovered and never delivered because the surface felt beneath him."},
  MAGICIAN_TRICKSTER: {"gift":"Bends reality with a spell and a laugh — and it works; transformation so charming that the world cooperates before it notices it changed.","curse":"Until it doesn't; the situation they cannot conjure their way out of becomes the teacher — and the pupil arrives furious at the lesson."},
  OUTLAW_ARTIST: {"gift":"Rebellion as raw expression: three chords and the truth; the scene, the zine, the noise that gives the unheard a sound and the polished lie a problem.","curse":"Mainstream absorption → rage at the machine that now sells the rage; authenticity policed until the scene eats itself; loudness mistaken for honesty."},
  OUTLAW_CAREGIVER: {"gift":"Rebellion driven purely by empathy: fights solely to free the oppressed and marginalised; force that exists entirely for someone else's unlocked door.","curse":"Compassion-fatigue → carries the world's pain until burnout; and the liberator's own chains — the ones no crowd cheers for — rust on unbroken."},
  OUTLAW_EXPLORER: {"gift":"Rebellion in motion: lives beyond the systems entirely; the renegade whose existence outside the walls proves the walls optional; freedom demonstrated, not argued.","curse":"Exile as identity → belongs nowhere on principle; the outside becomes its own cage; free from everything, for nothing."},
  OUTLAW_HERO: {"gift":"Disciplined force without a master: executes on pure conviction; the ronin whose code survived the death of every institution that once housed it.","curse":"Moral betrayal → unmoored; and the standing risk: reads everyone who fails the code as an enemy, when some are just fighting the same fight with less strength."},
  OUTLAW_INNOCENT: {"gift":"Rebellion with clean hands: refuses the corrupt order out of genuine faith in a better one; the idealist whose incorruptibility shames the cynics into motion.","curse":"The ideal compromised by allies → purism; splits every movement at ninety percent agreement; the perfect wielded as a weapon against the good."},
  OUTLAW_JUDGE: {"gift":"Principled opposition: the built-in counterweight; blocks the consensus precisely where it papers over a wrong; disagreement as a public service.","curse":"Agreement anywhere → suspicion; contradicts by reflex; the contrarian whose 'no' stopped carrying information because it never once said yes."},
  OUTLAW_LOVER: {"gift":"The spark in the crowd: turns private grievance into shared fire; the instigator whose passion makes the timid brave and the scattered one.","curse":"A crowd that cools → provokes to keep the heat; ignites conflicts for the feeling of the flame; the arsonist who misses the fire more than the cause."},
  OUTLAW_MAGICIAN: {"gift":"Disruption amplified by leverage: does not just storm the palace but rewires it; the revolution planned like a paradigm-shift — timing, symbols, structures ready for the morning after.","curse":"Allies' compromise → high treason; the engineered uprising becomes the engineer's possession; purges the revolution to protect the design of it."},
  OUTLAW_RULER: {"gift":"Rebellion that seizes the centre: does not petition the corrupt crown but takes it; the usurper whose coup replaces rot with something that actually governs.","curse":"The taken throne → becomes what it overthrew; guards the new crown with the old crown's methods; the revolution that ended the day it won."},
  OUTLAW_SAGE: {"gift":"Rebellion applied to dogma: dismantles false idols, dead religions, societal illusions with surgical argument; the hammer that is also a proof.","curse":"Intellectual laziness everywhere → extreme cynicism; isolates; smashes past the false idols into the load-bearing beliefs people actually live in."},
  OUTLAW_TRICKSTER: {"gift":"The absolute disruptor with perfect aim: freedom-drive plus salience-sight; breaks exactly the load-bearing lie and leaves the rest standing.","curse":"System-corruption everywhere → war-mode as home; the rage generalises; destroys everything standing, including the morning that needed a builder."},
  RULER_ARTIST: {"gift":"The realm as a designed thing: leadership that shapes not just order but MEANING — institutions with an aesthetic, structures people want to belong to.","curse":"Ugliness or compromise forced on the design → contempt for the inhabitants; the realm becomes a gallery where living is a violation of the concept."},
  RULER_CAREGIVER: {"gift":"Power as provision made systemic: builds the haven at scale — the ruler whose realm is a shelter, whose budget is an act of care.","curse":"Dependency or sacrifice demanded → smothering; provides so completely that no one is allowed to stand; control exercised through what is given."},
  RULER_EXPLORER: {"gift":"Structure meets the frontier: forges unmapped territory into working, profitable systems; the first to build where others still wander.","curse":"Market-failure or a closed frontier → ambition curdles to greed; people become raw material for the next expansion; motion mistaken for direction."},
  RULER_HERO: {"gift":"Order through the spearpoint: commands from the front, wins territory by will and discipline; the realm grows because its ruler bleeds first.","curse":"Weakness or a lost campaign → expansion becomes identity; crushes autonomy, reads every border as an insult; cannot stop because stopping feels like dying."},
  RULER_INNOCENT: {"gift":"Founding power fed by trust: builds institutions on the belief that people are worth building for; the charter that outlives its author because it was written in good faith.","curse":"Betrayal of the founding trust → the crash is total; either naïve doubling-down on a broken charter or a bitter founder who now audits every handshake."},
  RULER_JUDGE: {"gift":"Sovereign structure fused with the audit: a realm that not only stands but stands JUST — every rule weighed before it binds; authority people can appeal to.","curse":"Anarchy or an unappealable wrong inside the own system → the audit turns inward and merciless; governs by verdict, forgets to govern by care."},
  RULER_LOVER: {"gift":"Rule warmed by resonance: the patron whose power opens doors for what he loves — art, people, promise; authority that makes others flourish in its light.","curse":"Ingratitude or distance from the favoured → patronage turns to ownership; the beloved protégé becomes a possession, warmth becomes a debt to be repaid."},
  RULER_MAGICIAN: {"gift":"Dominion through leverage: does not storm the wall but owns the gate; reshapes markets, laws and loyalties until the world arrives at the intended order by itself.","curse":"The immovable — a will that cannot be bought or bent → grandiosity; the overlord who mistakes control of the board for control of the players' souls."},
  RULER_OUTLAW: {"gift":"Rebellion integrated into the hierarchy: breaks the corrupt part of the own system from within and replaces it standing; leads by natural authority, not inherited rank.","curse":"Bureaucracy or internal betrayal → own rule-breaking stops feeling like reform and starts feeling like treason; rigid defence of the 'new order' that was born to stay open."},
  RULER_SAGE: {"gift":"Plato's ideal through the pattern-reader: rule steered by comprehension of the deep structure; policy that is right decades before it is popular.","curse":"Irrationality of the governed → the tower seals; systems intellectually flawless and emotionally uninhabited; wisdom hardens into dogma that no longer listens."},
  RULER_TRICKSTER: {"gift":"Rule through the hidden string: reads every player's tell, steers the court by wit and timing; power that never needs to raise its voice because it moved first.","curse":"Being out-played or unmasked → control tightens to manipulation; everyone becomes a puppet, and a ruler of puppets reigns over an empty theatre."},
  SAGE_ARTIST: {"gift":"Insight that ships: turns comprehension into working things — theories into tools, patterns into products; the developer whose understanding compiles.","curse":"The elegant refactor without end → building postponed for understanding; or understanding skipped for building; the system rewritten forever, released never."},
  SAGE_CAREGIVER: {"gift":"Wisdom that carries: guides students and loved ones with vast intelligence used never to dominate; the mentor whose greatest works walk around on their own legs.","curse":"Failure of the student → carried as own failure; and the quiet dependency: needing the pupil's growth as oxygen; wisdom given with an invisible string."},
  SAGE_EXPLORER: {"gift":"Comprehension in motion: one long search for truth, fed by every new ground entered — borders, fields, disciplines crossed and understood. Depth that travelled for its breadth; a knowing kept alive by never letting the search close.","curse":"The archive as fortress → collects understanding as others collect territory; the footnote perfect, the application forever pending; learned about everything, changed by nothing."},
  SAGE_HERO: {"gift":"Truth-finding with directed action: will not rest until hidden patterns and invisible motives surface; comprehension that gets up from the desk and knocks on doors.","curse":"Unresolved anomalies → obsessive checking, paranoid voyeurism; the case that cannot close closes the detective instead."},
  SAGE_INNOCENT: {"gift":"The peak of internal reflection: steps outside the self, free of bias; clarity so complete it has stopped needing to win arguments; presence that quiets rooms.","curse":"Material confinement → dissociation; the enlightenment that floats free of the dishes, the traffic, the conversation without direction — and thereby of life."},
  SAGE_JUDGE: {"gift":"Disciplined doubt: tests every claim against evidence before it may live in the house; the skeptic whose 'prove it' keeps the whole community honest.","curse":"Doubt without a floor → corrodes everything including trust, love, and the own senses; the skeptic who demanded proof of the sunrise and missed it."},
  SAGE_LOVER: {"gift":"Teaching through devotion: wisdom transmitted inside a bond so warm the lesson is inseparable from the love; students who learned the material and became better people.","curse":"The devotion inflating → the pedestal; followers instead of students; the guru who started explaining truth and ended performing certainty for an audience that stopped questioning."},
  SAGE_MAGICIAN: {"gift":"Wisdom operationalised in silence: builds the structures, rites and standards that shape the world without signing them; influence exercised as architecture, not announcement.","curse":"Secrecy as a taste → the hidden hand starts preferring the hiding; knowledge hoarded as rank; the lodge that began as a school and calcified into a door-policy."},
  SAGE_OUTLAW: {"gift":"Conscious radical seclusion: decouples from the collective noise to hear the actual signal; returns from silence with what no meeting would ever have produced.","curse":"Forced interaction → extreme energy-leak; sacred solitude flips to misanthropy; the door barred so long the knock stops coming — and is missed."},
  SAGE_RULER: {"gift":"Philosophy applied to external order: structures raw theory into clear, irrefutable systems; the objective adviser whose analysis becomes the operating manual.","curse":"Ambiguity → analysis-paralysis; no decision survives the next variable; and the system that leaves no room for the irrational governs no actual humans."},
  SAGE_TRICKSTER: {"gift":"Play at the level of ideas: builds and breaks conceptual frames for sport; the theorist whose thought-experiments reveal which certainties were furniture all along.","curse":"Theory as evasion → everything reframed, nothing concluded; the elegant model preferred over the inconvenient measurement; games with frames while the house burns."},
  TRICKSTER_ARTIST: {"gift":"Truth through imitation: catches a person, a type, an era in one gesture; the impression so precise it functions as criticism, portrait and gift at once.","curse":"Only ever the mirror → the imitator's own face unused; celebrated for a hundred voices, silent in the one that is theirs."},
  TRICKSTER_CAREGIVER: {"gift":"Adaptive care through mimicry: becomes what each person needs — the joker for the grieving, the quiet one for the overwhelmed; camouflage in service of comfort.","curse":"Adapting as default → the own colour forgotten; reads the room so automatically that no room ever reads them; helpful in every shape, known in none."},
  TRICKSTER_EXPLORER: {"gift":"The world reread asroutes: sees passage where others see walls — over, under, through; obstacles converted to invitations at full speed; improvisation as a physical philosophy.","curse":"Stillness → unbearable; flows around every obstacle including the ones that deserved confronting; a life of perfect evasions and no landings."},
  TRICKSTER_HERO: {"gift":"Excellence with a grin: wins the contest and makes it look like play; the ace whose lightness is not the absence of discipline but its final form.","curse":"The streak ending → the grin is load-bearing; identity soldered to effortlessness; would rather not try than be seen trying and failing."},
  TRICKSTER_INNOCENT: {"gift":"Joy taken without permission: borrows the world for the fun of it; the joyride that harms no one and reminds everyone the rules were never the point of being alive.","curse":"The thrill needing escalation → recklessness; joy that must be stolen to count; the joyrider who cannot enjoy what is freely given, including love."},
  TRICKSTER_JUDGE: {"gift":"Truth through opposition: argues the indefensible so brilliantly that the room finally examines what it believed; the devil's advocate as the immune system of judgement.","curse":"The role consuming the person → contrarian in the marrow; wins every argument and holds no position; a mind that can defend anything and stand for nothing."},
  TRICKSTER_LOVER: {"gift":"Desire disarmed by play: seduction that is honest about being a game and generous in the playing; awakens people to their own magnetism.","curse":"The game preferred over the prize → collects beginnings; when someone stays, the seducer flees the ending of the chase; charm as a moat around the heart."},
  TRICKSTER_MAGICIAN: {"gift":"Constant change of form, identity, perspective as an instrument: plays with the fabric of perception deliberately; shows others their fixed self was always a costume choice.","curse":"No fixed form → can become ruthlessly manipulative or fall into identity-void; the shapeshifter gravity finally catches: every form was real, and none was home."},
  TRICKSTER_OUTLAW: {"gift":"Truth as a way of moving: the Fool does not say the unsayable — he walks it. Every entrance, gesture and departure unfiltered; a being so free it cannot be placed, bought, or prepared for. Where he walks, pretence has to reorganise around him.","curse":"The walk absorbed as entertainment — the order applauds and nothing moves → the gait becomes the mask; the free step performed long after it stopped being free; the fool who walked everywhere except inward — the one road that was eating him."},
  TRICKSTER_RULER: {"gift":"Sees every structure as a built thing: the frames around power are constructions, and he can read the joinery. Where others see walls he sees assembly — the frame around the throne was never load-bearing, and now everyone has seen it.","curse":"no order left worth exposing → nothing can contain him; belonging reads as capture; the one who saw through every structure can no longer be held by any, including the ones that hold a life together."},
  TRICKSTER_SAGE: {"gift":"Disruption through the riddle: wraps the deepest observations in puzzles that make people THINK their way to the truth; the answer earned lands deeper than the answer given.","curse":"Clarity refused on principle → obscurity as superiority; riddles with no answer, asked to stay untouchable; the riddler nobody solves because nothing was hidden."},
};

const cell = (key, lang) => {
  const k = String(key || '').toUpperCase();
  const table = String(lang).toLowerCase().startsWith('en') ? EXTENSION_CELLS_EN : EXTENSION_CELLS_NL;
  return table[k] || EXTENSION_CELLS_NL[k] || null;
};

/** The ratified gift of MAIN_SUPPORT, or '' when the key is unknown. */
export function getExtensionGift(mainKey, supportKey, lang = 'nl') {
  return (cell(`${mainKey}_${supportKey}`, lang) || {}).gift || '';
}

/** The ratified curse (vloek / trigger) of MAIN_SUPPORT, or '' when the key is unknown. */
export function getExtensionCurse(mainKey, supportKey, lang = 'nl') {
  return (cell(`${mainKey}_${supportKey}`, lang) || {}).curse || '';
}

export { EXTENSION_CELLS_NL, EXTENSION_CELLS_EN };
